
/**
 * Cloudflare Worker responsible for securely signing Cloudinary uploads.
 */
const CLOUDINARY_SIGNING_URL = 'https://cowplugng-cloudinary-sign.tugbobodare4.workers.dev';
const CLOUDINARY_UPLOAD_PRESET = 'cowplugng_documents';

export interface CloudinaryUploadResult {
  url: string;
  publicId: string;
}

/**
 * Upload a file to Cloudinary using a signature generated by our Cloudflare Worker.
 */
/**
 * Upload a file to Cloudinary using a signature generated by our Cloudflare Worker.
 */
export async function uploadToCloudinary(
  file: File,
  userId: string,
  category: string = 'general',
  allowLocalFallback: boolean = true
): Promise<CloudinaryUploadResult> {
  if (file.size > 10 * 1024 * 1024) {
    throw new Error("File too large. Maximum size is 10 MB.");
  }

  let signingData: any = null;
  try {
    const signingResponse = await fetch(CLOUDINARY_SIGNING_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        userId,
        side: (category === 'front' || category === 'back') ? category : 'front',
      }),
    });

    if (signingResponse.ok) {
      signingData = await signingResponse.json();
    }
  } catch (err) {
    console.warn("Signing worker unreachable, falling back to local data URL:", err);
  }

  if (!signingData || !signingData.signature || !signingData.cloudName) {
    if (!allowLocalFallback) throw new Error("Upload service unavailable. Please try again.");
    // Fallback: convert file to base64 Data URL so upload never fails with "Failed to fetch"
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        resolve({
          url: reader.result as string,
          publicId: `local_${Date.now()}_${file.name}`
        });
      };
      reader.onerror = (error) => reject(error);
      reader.readAsDataURL(file);
    });
  }

  const uploadData = new FormData();
  uploadData.append('file', file);
  uploadData.append('api_key', signingData.apiKey);
  uploadData.append('timestamp', String(signingData.timestamp));
  uploadData.append('signature', signingData.signature);
  uploadData.append('upload_preset', CLOUDINARY_UPLOAD_PRESET);

  try {
    const uploadResponse = await fetch(
      `https://api.cloudinary.com/v1_1/${signingData.cloudName}/auto/upload`,
      {
        method: 'POST',
        body: uploadData,
      }
    );

    let result: any = {};
    try {
      result = await uploadResponse.json();
    } catch {
      throw new Error('Cloudinary returned an invalid response.');
    }

    if (!uploadResponse.ok || !result.secure_url) {
      throw new Error(result?.error?.message || 'Cloudinary file upload failed.');
    }

    return {
      url: result.secure_url,
      publicId: result.public_id || `cloudinary_${Date.now()}`,
    };
  } catch (cloudinaryErr: any) {
    if (!allowLocalFallback) throw new Error("Upload service unavailable. Please try again.");
    console.warn("Cloudinary direct upload failed, falling back to data URL:", cloudinaryErr);
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        resolve({
          url: reader.result as string,
          publicId: `local_${Date.now()}_${file.name}`
        });
      };
      reader.onerror = (error) => reject(error);
      reader.readAsDataURL(file);
    });
  }
}

